/// Situação de um pedido.
create static entity StatusPedido public (
  Id Integer identifier required,
  Label Text(50) required,
  Order Integer required
)
values
  Aberto (Id = 1, Label = "Aberto", Order = 1),
  Fechado (Id = 2, Label = "Fechado", Order = 2);
/// Pedido de um cliente.
create entity Pedido public (
  Id Long Integer identifier auto required,
  Numero Text(20) required,
  StatusPedidoId StatusPedido Identifier required references StatusPedido on delete Protect,
  Total Decimal(18,2) default 0,
  CriadoEm Date Time required
);
create unique index UQ_Pedido_Numero on Pedido (Numero);
type PedidoResumo public = {
  Numero: Text(20);
  Total: Decimal(18,2);
}
site property LimitePedidos: Integer = 50

